// Each way a user activates the theme control.
const activations = {
  click: (control) => control.click(),
  "the Enter key": (control) => control.press("Enter"),
  "the Space key": (control) => control.press("Space"),
};

function themeControl(page) {
  return page.locator("#theme-toggle");
}

// The data-theme value one activation must produce from the current value.
function nextTheme(current) {
  if (current === "light") return "dark";
  if (current === "dark") return "light";
  return /^(light|dark)$/;
}

async function activateOnce(page, activate) {
  const html = page.locator("html");
  const before = await html.getAttribute("data-theme");
  await activate(themeControl(page));
  await expect(html).toHaveAttribute("data-theme", nextTheme(before));
  return html.getAttribute("data-theme");
}

async function useControlToSet(page, theme, activate) {
  await expect(themeControl(page)).toBeVisible();
  let current = await activateOnce(page, activate);
  if (current !== theme) {
    current = await activateOnce(page, activate);
  }
  await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
}

async function reopen(page, context) {
  await page.close();
  const reopened = await context.newPage();
  await reopened.goto("index.html");
  return reopened;
}

