    let current = await activateOnce(page, activate);
    for (const step of ["second", "third", "fourth"]) {
      const background = await body.evaluate((element) => getComputedStyle(element).backgroundColor);
      const next = nextTheme(current);
      await activate(themeControl(page));
      await expect(page.locator("html"), `${step} activation`).toHaveAttribute("data-theme", next);
      await expect(body, `${step} activation`).not.toHaveCSS("background-color", background);
      current = next;
    }
  });
}

