  { label: "focus on the document body", locate: null },
  { label: "focus on digit button 1", locate: (page) => button(page, "1") },
  { label: "focus on operator button +", locate: (page) => button(page, "+") },
  { label: "focus on decimal point button", locate: (page) => button(page, ".") },
  { label: "focus on equals button", locate: (page) => button(page, "=") },
  { label: "focus on clear button C", locate: (page) => button(page, "C") },
  { label: "focus on backspace/delete button", locate: (page) => page.getByRole("button", { name: /backspace|delete|⌫/i }) },
  { label: "focus on the theme control", locate: (page) => page.locator("#theme-toggle") },
];

async function openWithFocus(page, condition) {
  await page.goto("index.html");
  await expect(display(page)).toBeVisible();
  if (condition.locate) {
    const element = condition.locate(page);
    await element.focus();
    await expect(element).toBeFocused();
  }
}

async function pressSequence(page, keys) {
  for (const key of keys) {
    await page.keyboard.press(key);
  }
}

for (const condition of FOCUS_CONDITIONS) {
  test(`AC-013 After a fresh page load, with focus on the page document, pressing the keyboard keys 9, *, 3, Enter in sequence results in the display area showing the value 27. (${condition.label})`, async ({ page }) => {
    await openWithFocus(page, condition);
    await pressSequence(page, ["9", "*", "3", "Enter"]);
    await expect(display(page)).toHaveText(showsValue("27"));
  });

  test(`AC-014 After a fresh page load, with focus on the page document, pressing the keyboard keys 2, +, 3, Enter in sequence results in the display area showing the value 5. (${condition.label})`, async ({ page }) => {
    await openWithFocus(page, condition);
    await pressSequence(page, ["2", "+", "3", "Enter"]);
    await expect(display(page)).toHaveText(showsValue("5"));
  });

  test(`AC-015 After a fresh page load, with focus on the page document, pressing the keyboard keys 8, /, 4, Enter in sequence results in the display area showing the value 2. (${condition.label})`, async ({ page }) => {
    await openWithFocus(page, condition);
    await pressSequence(page, ["8", "/", "4", "Enter"]);
    await expect(display(page)).toHaveText(showsValue("2"));
  });

  test(`AC-016 After a fresh page load, with focus on the page document, pressing the keyboard keys 4, ., 5 and then Backspace results in the display area text containing 4. and not containing 4.5. (${condition.label})`, async ({ page }) => {
    await openWithFocus(page, condition);
    await pressSequence(page, ["4", ".", "5", "Backspace"]);
    await expect(display(page)).toHaveText(/4\./);
    await expect(display(page)).not.toHaveText(/4\.5/);
  });

  test(`AC-017 After a fresh page load, with focus on the page document, pressing the keyboard keys 5, +, 3 and then Escape results in the display area showing exactly the same text it showed on the fresh page load. (${condition.label})`, async ({ page }) => {
    await openWithFocus(page, condition);
    const freshText = await display(page).textContent();
    await pressSequence(page, ["5", "+", "3", "Escape"]);
    await expect(display(page)).toHaveText(freshText);
  });

  test(`AC-024 After a fresh page load, with focus on the page document, pressing the keyboard keys 9, -, 4, Enter in sequence results in the display area showing the value 5. (${condition.label})`, async ({ page }) => {
    await openWithFocus(page, condition);
    await pressSequence(page, ["9", "-", "4", "Enter"]);
    await expect(display(page)).toHaveText(showsValue("5"));
  });
}

